const assets={"/":{"body":"<!DOCTYPE html><html lang=\"pt-BR\"><head><meta charset=\"UTF-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>Agendamento | Jaiane Neves</title><link href=\"https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600&family=Playfair+Display:ital,wght@0,400;1,400&display=swap\" rel=\"stylesheet\"><link rel=\"stylesheet\" href=\"styles.css\"></head><body><header><a class=\"brand\" href=\"/\">Jaiane Neves<small>PROGRESSIVA & SELAGEM</small></a><a href=\"/admin\" class=\"outline\">Área da profissional ↗</a></header><main><div class=\"intro\"><span class=\"eyebrow\">UM TEMPO SÓ SEU</span><h1>Agende seu momento de <em>cuidado.</em></h1><p>Escolha seu serviço e o melhor horário para você.</p></div><form id=\"bookingForm\"><div class=\"grid\"><section class=\"panel\"><div class=\"section-title\"><span class=\"step\">01</span><div><h2>Seu cuidado</h2><p>Conte um pouquinho sobre você.</p></div></div><label for=\"name\">Seu nome</label><input id=\"name\" placeholder=\"Como podemos chamar você?\" autocomplete=\"name\" required minlength=\"2\" maxlength=\"100\"><label for=\"phone\">WhatsApp</label><input id=\"phone\" type=\"tel\" placeholder=\"(00) 00000-0000\" autocomplete=\"tel\" required maxlength=\"16\"><label for=\"service\">Qual serviço você deseja?</label><select id=\"service\" required></select><label for=\"hairLength\">Comprimento do cabelo</label><select id=\"hairLength\" required><option value=\"\">Selecione o comprimento</option><option value=\"curto\">Curto</option><option value=\"medio\">Médio</option><option value=\"longo\">Longo</option><option value=\"extralongo\">Extra longo</option></select><p class=\"hint price-info\">O valor depende do comprimento do cabelo e será confirmado após avaliação.</p><div class=\"detail\"><span>Profissional</span><strong>Jaiane Neves</strong></div><div class=\"detail\"><span>Duração estimada</span><strong id=\"duration\"></strong></div><div class=\"care\">✧<p>Um momento para desacelerar<br>e realçar sua beleza.</p></div></section><section class=\"panel\"><div class=\"section-title\"><span class=\"step\">02</span><div><h2>Seu melhor momento</h2><p>Escolha uma data e um horário disponível.</p></div></div><div class=\"calendar-head\"><h3 id=\"monthLabel\" aria-live=\"polite\"></h3><div><button type=\"button\" id=\"prevMonth\" aria-label=\"Mês anterior\">‹</button><button type=\"button\" id=\"nextMonth\" aria-label=\"Próximo mês\">›</button></div></div><div class=\"weekdays\" aria-hidden=\"true\"><span>DOM</span><span>SEG</span><span>TER</span><span>QUA</span><span>QUI</span><span>SEX</span><span>SÁB</span></div><div id=\"calendarDays\" class=\"calendar-days\" role=\"group\" aria-label=\"Escolha uma data\"></div><div class=\"legend\"><span>• Disponível</span><span>● Selecionado</span><s>Indisponível</s></div><div class=\"times-heading\"><h3>Horários disponíveis</h3><span id=\"selectedDateLabel\"></span></div><div id=\"times\" class=\"times\" role=\"group\" aria-label=\"Escolha um horário\"></div><p id=\"timeHint\" class=\"hint\" aria-live=\"polite\"></p></section></div><div class=\"checkout panel\"><div><span class=\"eyebrow\">SEU AGENDAMENTO</span><p id=\"selectionSummary\"></p></div><div class=\"checkout-action\"><div class=\"total\"><small>Valor conforme o comprimento</small><strong id=\"price\"></strong></div><button class=\"button\" type=\"submit\">Reservar horário ↗</button></div><p id=\"formStatus\" role=\"status\"></p></div></form><p class=\"demo\">O valor será confirmado após avaliação do comprimento do cabelo.<br>Duração provisória de 2h por serviço. Atendimento de segunda a sábado, das 9h às 18h.<br>Ao reservar, seu nome e WhatsApp serão usados pelo salão para organizar e confirmar seu atendimento.</p></main><footer><span>Jaiane Neves</span><p>Beleza em cada detalhe. Cuidado em cada momento.</p></footer><script src=\"script.js\"></script></body></html>\r\n","type":"text/html; charset=utf-8"},"/styles.css":{"body":"﻿:root{--gold:#957020;--dark:#765619;--soft:#f4eddb;--ink:#363229;--muted:#827d72;--line:#eae5da}*{box-sizing:border-box}body{margin:0;background:#faf8f3;color:var(--ink);font:14px 'DM Sans',sans-serif}button,input,select{font:inherit}button{cursor:pointer}button:disabled{cursor:default}a{color:inherit;text-decoration:none}header{background:white;padding:22px 7%;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid var(--line);gap:15px}.brand{font:28px 'Playfair Display',Georgia,serif}.brand small{display:block;font:8px 'DM Sans',sans-serif;letter-spacing:4px;text-align:center;margin-top:7px}.outline{background:white;border:1px solid var(--line);border-radius:6px;padding:12px 17px;color:var(--gold);font-size:11px}main{max-width:1110px;margin:auto;padding:36px 25px 24px}.intro{text-align:center;margin-bottom:30px}.eyebrow{font-size:9px;letter-spacing:2px;color:var(--gold);font-weight:600}h1,h2,h3{font-family:'Playfair Display',Georgia,serif;font-weight:400;margin:0}h1{font-size:39px;margin:10px 0}em{color:var(--gold)}p{color:var(--muted);line-height:1.7}.intro p{font-size:12px;margin:10px 0}.grid{display:grid;grid-template-columns:.82fr 1.18fr;gap:22px}.panel{background:white;border:1px solid var(--line);border-radius:12px;padding:29px 32px}.section-title{display:flex;gap:14px;align-items:center;margin-bottom:27px}.step{background:var(--soft);color:var(--gold);border:1px solid #e7dabb;border-radius:50%;width:35px;height:35px;display:grid;place-items:center;font-size:11px;flex-shrink:0}h2{font-size:24px}.section-title p{margin:5px 0 0;font-size:11px}label{display:block;font-size:11px;font-weight:500;margin-bottom:9px}input,select{width:100%;height:46px;border:1px solid var(--line);border-radius:6px;background:white;color:var(--ink);padding:0 13px;margin-bottom:23px;font-size:12px}input::placeholder{color:#a09b92}input:focus,select:focus{outline:2px solid #b88b30;outline-offset:2px}.detail{display:flex;justify-content:space-between;font-size:11px;margin:17px 0;gap:10px}.detail span{color:var(--muted)}.detail strong{font-weight:500}.care{display:flex;gap:16px;align-items:center;border-top:1px solid var(--line);margin-top:25px;padding-top:20px;font-size:35px;color:#b99a52}.care p{font:italic 18px/1.5 'Playfair Display',Georgia,serif;margin:0;color:var(--gold)}.calendar-head{display:flex;align-items:center;justify-content:space-between;margin-bottom:18px}.calendar-head h3{font:500 14px 'DM Sans',sans-serif;text-transform:capitalize}.calendar-head button{border:1px solid var(--line);background:white;border-radius:5px;color:var(--gold);width:29px;height:29px;font-size:23px;line-height:1;margin-left:7px}.calendar-head button:disabled{opacity:.25}.weekdays,.calendar-days{display:grid;grid-template-columns:repeat(7,1fr);gap:5px}.weekdays{text-align:center;font-size:8px;letter-spacing:.8px;color:var(--muted);margin-bottom:9px}.day{border:1px solid transparent;background:white;border-radius:6px;min-height:37px;color:var(--ink);font-size:11px;position:relative}.day:not(:disabled)::after{content:'';position:absolute;bottom:4px;left:calc(50% - 1.5px);width:3px;height:3px;background:#b99a52;border-radius:50%}.day:hover:not(:disabled){background:var(--soft)}.day.today{border-color:#d3be8a}.day.selected{background:var(--gold)!important;color:white}.day.selected::after{background:white}.day:disabled{color:#c8c4bb;text-decoration:line-through;background:#fcfbf9}.legend{display:flex;justify-content:center;gap:18px;font-size:8px;color:var(--gold);margin:16px 0 23px}.legend s{color:#aaa59a}.times-heading{display:flex;justify-content:space-between;align-items:center;border-top:1px solid var(--line);padding-top:21px;gap:10px;margin-bottom:14px}.times-heading h3{font:500 12px 'DM Sans',sans-serif}.times-heading>span{font-size:10px;color:var(--gold)}.times{display:grid;grid-template-columns:repeat(5,1fr);gap:8px}.time{border:1px solid var(--line);background:white;border-radius:5px;font-size:11px;padding:10px 3px;color:var(--ink)}.time:hover{border-color:var(--gold);background:var(--soft)}.time.selected{background:var(--gold);border-color:var(--gold);color:white}.hint{font-size:10px;line-height:1.6;margin:12px 0 0}.checkout{margin-top:22px;padding:23px 30px;display:flex;justify-content:space-between;align-items:center;gap:20px;flex-wrap:wrap}.checkout p{font-size:12px;margin:6px 0 0}.checkout-action{display:flex;align-items:center;gap:28px}.total{text-align:right}.total small{display:block;font-size:9px;color:var(--muted);margin-bottom:4px}.total strong{font-size:21px;font-weight:500}.button{border:1px solid var(--gold);background:var(--gold);color:white;padding:17px 25px;border-radius:6px;font-size:12px}.button:hover{background:var(--dark)}#formStatus{flex-basis:100%;color:var(--gold);margin:0}#formStatus:empty{display:none}.demo{text-align:center;font-size:9px;margin:20px 0 0;line-height:1.8}footer{padding:22px 7%;display:flex;justify-content:space-between;align-items:center;border-top:1px solid var(--line);gap:15px;color:var(--muted)}footer>span{font:20px 'Playfair Display',Georgia,serif}footer p{font-size:9px;margin:0}button:focus-visible,a:focus-visible{outline:2px solid #b88b30;outline-offset:3px}dialog{border:1px solid var(--line);border-radius:12px;padding:28px;width:min(520px,90vw);max-height:80vh;color:var(--ink)}dialog::backdrop{background:#302e2b77;backdrop-filter:blur(3px)}.dialog-top{display:flex;justify-content:space-between;align-items:center;gap:10px}.dialog-top button{border:0;background:white;font-size:28px;color:var(--muted)}.saved-booking{border-top:1px solid var(--line);padding:18px 0;margin-top:15px}.saved-booking strong{display:block}.saved-booking p{font-size:12px}.cancel{border:1px solid var(--line);background:white;color:var(--gold);padding:9px 12px;border-radius:5px;font-size:11px}@media(max-width:760px){main{padding:30px 18px 22px}h1{font-size:31px}.grid{grid-template-columns:1fr;gap:17px}.panel{padding:25px}.care{display:none}.checkout-action{width:100%;justify-content:space-between}.total{text-align:left}.section-title{margin-bottom:23px}footer p{display:none}}@media(max-width:390px){header{padding:19px 18px}.brand{font-size:23px}.outline{padding:10px;font-size:9px}.panel{padding:21px 18px}.legend{gap:10px}.times{grid-template-columns:repeat(4,1fr)}.checkout-action{gap:12px}.button{padding:15px}h1{font-size:28px}}\r\n\n[hidden]{display:none!important}.login-panel{max-width:440px;margin:0 auto}.login-panel form{margin-top:24px}.admin-toolbar{display:flex;align-items:end;gap:12px;flex-wrap:wrap}.admin-toolbar input{margin:0}.admin-toolbar .outline{height:46px}.admin-booking{display:flex;align-items:center;justify-content:space-between;gap:20px;margin-top:14px}.admin-booking p{margin:7px 0;font-size:12px}.admin-booking a{color:var(--gold);font-size:12px}.price-info{margin:-10px 0 20px}.total strong{font-size:14px}.button:disabled{opacity:.6;cursor:wait}.outline{display:inline-block}.login-panel .button{width:100%}#passwordForm{margin-top:22px}#passwordForm .hint{margin-bottom:18px}@media(max-width:600px){.admin-booking{align-items:start;flex-direction:column}.total{max-width:155px}.brand small{letter-spacing:2px}}\n","type":"text/css; charset=utf-8"},"/script.js":{"body":"const services=[{id:'progressiva',name:'Progressiva',duration:120,price:null},{id:'selagem',name:'Selagem',duration:120,price:null}];\nconst $=id=>document.getElementById(id),key='jaiane-neves-bookings-v1',money=n=>n==null?'A combinar':n.toLocaleString('pt-BR',{style:'currency',currency:'BRL'});\nlet busyBookings=[],availabilityReady=false,loadingMonth=0;\nlet selectedDate='',selectedTime='',viewMonth=new Date(new Date().getFullYear(),new Date().getMonth(),1);\nfunction localDate(d=new Date()){return new Intl.DateTimeFormat(\"en-CA\",{timeZone:\"America/Sao_Paulo\",year:\"numeric\",month:\"2-digit\",day:\"2-digit\"}).format(d)}\nfunction readBookings(){return busyBookings}\nconst minutes=t=>Number(t.split(':')[0])*60+Number(t.split(':')[1]),currentService=()=>services.find(s=>s.id===$('service').value);\nfunction slotsFor(date){const s=currentService(),now=new Date();if(!availabilityReady||!date||date<localDate(now)||new Date(date+'T12:00:00').getDay()===0)return [];const booked=readBookings().filter(b=>b.date===date),slots=[];for(let hour=9;hour<18;hour++){const start=hour*60;if(date===localDate(now)&&start<=salonMinutes(now))continue;if(start+s.duration>1080)continue;if(booked.some(b=>start<minutes(b.time)+b.duration&&start+s.duration>minutes(b.time)))continue;slots.push(`${String(hour).padStart(2,'0')}:00`)}return slots}\nfunction renderCalendar(){const now=new Date(),first=new Date(now.getFullYear(),now.getMonth(),1);$('monthLabel').textContent=viewMonth.toLocaleDateString('pt-BR',{month:'long',year:'numeric'});$('prevMonth').disabled=viewMonth<=first;$('calendarDays').replaceChildren();for(let i=0;i<viewMonth.getDay();i++){const blank=document.createElement('span');blank.setAttribute('aria-hidden','true');$('calendarDays').append(blank)}const days=new Date(viewMonth.getFullYear(),viewMonth.getMonth()+1,0).getDate();for(let day=1;day<=days;day++){const d=new Date(viewMonth.getFullYear(),viewMonth.getMonth(),day),date=localDate(d),button=document.createElement('button'),available=slotsFor(date).length>0&&date<=maxDate();button.type='button';button.className='day';button.textContent=day;button.disabled=!available;button.setAttribute('aria-label',`${d.toLocaleDateString('pt-BR',{weekday:'long',day:'numeric',month:'long',year:'numeric'})}${available?'':', indisponível'}`);button.setAttribute('aria-pressed',String(selectedDate===date));if(date===localDate(now)){button.classList.add('today');button.setAttribute('aria-current','date')}if(date===selectedDate)button.classList.add('selected');button.onclick=()=>{selectedDate=date;selectedTime='';$('formStatus').textContent='';renderCalendar();renderTimes()};$('calendarDays').append(button)}}\nfunction updateSummary(){const s=currentService();$('duration').textContent=`${s.duration} minutos`;$('price').textContent='Após avaliação';$('selectionSummary').textContent=selectedDate?`${s.name} · ${new Date(selectedDate+'T12:00:00').toLocaleDateString('pt-BR')}${selectedTime?' às '+selectedTime:' · Escolha um horário'}`:'Selecione uma data e um horário.'}\nfunction renderTimes(){const slots=slotsFor(selectedDate);if(!slots.includes(selectedTime))selectedTime='';$('times').replaceChildren();$('selectedDateLabel').textContent=selectedDate?new Date(selectedDate+'T12:00:00').toLocaleDateString('pt-BR',{day:'2-digit',month:'long'}):'';slots.forEach(time=>{const button=document.createElement('button');button.type='button';button.className='time'+(selectedTime===time?' selected':'');button.textContent=time;button.setAttribute('aria-pressed',String(selectedTime===time));button.onclick=()=>{selectedTime=time;$('formStatus').textContent='';renderTimes()};$('times').append(button)});$('timeHint').textContent=!selectedDate?'Selecione um dia no calendário para ver os horários.':slots.length?'Somente horários livres para o serviço selecionado.':'Não há mais horários disponíveis. Escolha outra data.';updateSummary()}\n$('prevMonth').onclick=()=>{viewMonth=new Date(viewMonth.getFullYear(),viewMonth.getMonth()-1,1);selectedDate='';selectedTime='';loadAvailability()};$('nextMonth').onclick=()=>{viewMonth=new Date(viewMonth.getFullYear(),viewMonth.getMonth()+1,1);selectedDate='';selectedTime='';loadAvailability()};services.forEach(s=>{const option=document.createElement('option');option.value=s.id;option.textContent=s.name;$('service').append(option)});$('service').onchange=()=>{selectedTime='';renderCalendar();renderTimes()};renderCalendar();renderTimes();\n$('phone').addEventListener('input',e=>{const v=e.target.value.replace(/\\D/g,'').slice(0,11);e.target.value=v.length>6?`(${v.slice(0,2)}) ${v.slice(2,-4)}-${v.slice(-4)}`:v.length>2?`(${v.slice(0,2)}) ${v.slice(2)}`:v});\n\nfunction salonMinutes(d){const p=Object.fromEntries(new Intl.DateTimeFormat('en-US',{timeZone:'America/Sao_Paulo',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).formatToParts(d).map(p=>[p.type,p.value]));return Number(p.hour)*60+Number(p.minute)}\nfunction maxDate(){const d=new Date(localDate()+'T12:00:00Z');d.setUTCFullYear(d.getUTCFullYear()+1);return d.toISOString().slice(0,10)}\nasync function loadAvailability(){const request=++loadingMonth;availabilityReady=false;renderCalendar();renderTimes();$('timeHint').textContent='Consultando horários disponíveis…';try{const month=localDate(new Date(viewMonth.getFullYear(),viewMonth.getMonth(),15)),r=await fetch('/api/availability?month='+month.slice(0,7)),data=await r.json();if(request!==loadingMonth)return;if(!r.ok)throw new Error(data.error||'Não foi possível consultar a agenda.');busyBookings=data.bookings;availabilityReady=true;renderCalendar();renderTimes()}catch(e){if(request!==loadingMonth)return;$('timeHint').textContent=e.message+' Atualize a página para tentar novamente.'}}\n$('bookingForm').onsubmit=async e=>{e.preventDefault();const status=$('formStatus'),button=e.submitter;if($('name').value.trim().length<2||$('phone').value.replace(/\\D/g,'').length<10){status.textContent='Preencha seu nome e um telefone válido com DDD.';return}if(!selectedDate||!selectedTime||!slotsFor(selectedDate).includes(selectedTime)){status.textContent='Selecione uma data e um horário disponível.';return}button.disabled=true;const booking={service:$('service').value,date:selectedDate,time:selectedTime,name:$('name').value.trim(),phone:$('phone').value,hairLength:$('hairLength').value};status.textContent='Confirmando seu horário…';try{const r=await fetch('/api/bookings',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(booking)}),data=await r.json();if(!r.ok){if(r.status===409){selectedTime='';await loadAvailability()}throw new Error(data.error||'Não foi possível agendar.')}selectedTime='';await loadAvailability();status.textContent=`Agendamento confirmado: ${data.service}, ${new Date(data.date+'T12:00:00').toLocaleDateString('pt-BR')} às ${data.time}. Valor confirmado após avaliação do cabelo.`;$('name').value='';$('phone').value=''}catch(error){status.textContent=error.message}finally{button.disabled=false}};\nwindow.addEventListener('focus',loadAvailability);loadAvailability();\n","type":"text/javascript; charset=utf-8"},"/admin":{"body":"<!DOCTYPE html><html lang=\"pt-BR\"><head><meta charset=\"UTF-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>Área administrativa | Jaiane Neves</title><link href=\"https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600&family=Playfair+Display:ital,wght@0,400;1,400&display=swap\" rel=\"stylesheet\"><link rel=\"stylesheet\" href=\"/styles.css\"></head><body><header><a class=\"brand\" href=\"/\">Jaiane Neves<small>PROGRESSIVA & SELAGEM</small></a><a class=\"outline\" href=\"/\">Voltar ao agendamento ↗</a></header><main><div class=\"intro\"><span class=\"eyebrow\">ÁREA EXCLUSIVA</span><h1>Sua agenda, <em>em um só lugar.</em></h1><p>Gerencie os agendamentos de progressiva e selagem.</p></div><section id=\"loginPanel\" class=\"panel login-panel\"><h2>Acesso da profissional</h2><p class=\"hint\">Entre com sua senha para consultar os agendamentos.</p><form id=\"loginForm\"><label for=\"password\">Senha</label><input id=\"password\" type=\"password\" autocomplete=\"current-password\" required maxlength=\"128\"><button class=\"button\" type=\"submit\">Entrar na agenda ↗</button><p id=\"loginStatus\" class=\"hint\" role=\"status\"></p></form></section><section id=\"adminPanel\" hidden><div class=\"panel admin-toolbar\"><div><label for=\"filterDate\">Filtrar por data</label><input type=\"date\" id=\"filterDate\"></div><button type=\"button\" id=\"clearFilter\" class=\"outline\">Todas as datas</button><button type=\"button\" id=\"refresh\" class=\"outline\">Atualizar</button><button type=\"button\" id=\"changePassword\" class=\"outline\">Alterar senha</button><button type=\"button\" id=\"logout\" class=\"outline\">Sair</button></div><p id=\"adminStatus\" role=\"status\" class=\"hint\"></p><div id=\"adminBookings\" aria-live=\"polite\"></div><p class=\"hint\">Valores conforme o comprimento do cabelo, confirmados após avaliação. Duração provisória: 2 horas por atendimento.</p></section></main><dialog id=\"passwordDialog\"><div class=\"dialog-top\"><h2>Alterar senha</h2><button id=\"closePassword\" type=\"button\" aria-label=\"Fechar\">×</button></div><form id=\"passwordForm\"><label for=\"currentPassword\">Senha atual</label><input id=\"currentPassword\" type=\"password\" autocomplete=\"current-password\" required maxlength=\"128\"><label for=\"newPassword\">Nova senha</label><input id=\"newPassword\" type=\"password\" autocomplete=\"new-password\" minlength=\"12\" maxlength=\"128\" required><p class=\"hint\">Use pelo menos 12 caracteres. Ao alterar, será necessário entrar novamente.</p><button class=\"button\" type=\"submit\">Salvar nova senha</button><p id=\"passwordStatus\" class=\"hint\" role=\"status\"></p></form></dialog><script src=\"/admin.js\"></script></body></html>\n","type":"text/html; charset=utf-8"},"/admin.js":{"body":"const $=id=>document.getElementById(id);\nasync function api(path,options={}){const r=await fetch(path,{...options,headers:{'Content-Type':'application/json',...options.headers}});const data=await r.json();if(!r.ok){const e=new Error(data.error||'Não foi possível concluir.');e.status=r.status;throw e}return data}\nfunction showLogin(message=''){$('adminPanel').hidden=true;$('loginPanel').hidden=false;$('adminBookings').replaceChildren();$('loginStatus').textContent=message}\nfunction showAdmin(){$('loginPanel').hidden=true;$('adminPanel').hidden=false;$('password').value=''}\nasync function load(){try{$('adminStatus').textContent='Carregando agenda…';const date=$('filterDate').value,data=await api('/api/admin/bookings'+(date?'?date='+encodeURIComponent(date):''));showAdmin();$('adminBookings').replaceChildren();$('adminStatus').textContent=data.bookings.length?`${data.bookings.length} agendamento(s) encontrado(s).`:'Nenhum agendamento encontrado.';data.bookings.forEach(b=>{const card=document.createElement('article');card.className='panel admin-booking';const info=document.createElement('div'),title=document.createElement('h2'),detail=document.createElement('p'),contact=document.createElement('a'),size=document.createElement('p');title.textContent=b.name;detail.textContent=`${b.service} · ${new Date(b.date+'T12:00:00').toLocaleDateString('pt-BR')} às ${b.time}`;contact.textContent=b.phone;contact.href='https://wa.me/55'+b.phone.replace(/\\D/g,'');contact.target='_blank';contact.rel='noopener noreferrer';size.className='hint';size.textContent='Comprimento: '+({curto:'Curto',medio:'Médio',longo:'Longo',extralongo:'Extra longo'}[b.hair_length]||'Não informado');info.append(title,detail,contact,size);const cancel=document.createElement('button');cancel.type='button';cancel.className='cancel';cancel.textContent='Cancelar agendamento';cancel.onclick=async()=>{if(!confirm(`Cancelar o agendamento de ${b.name}?`))return;cancel.disabled=true;try{await api('/api/admin/bookings/'+encodeURIComponent(b.id),{method:'DELETE'});await load()}catch(e){$('adminStatus').textContent=e.message;cancel.disabled=false}};card.append(info,cancel);$('adminBookings').append(card)})}catch(e){if(e.status===401)showLogin();else $('adminStatus').textContent=e.message}}\n$('loginForm').onsubmit=async e=>{e.preventDefault();const button=e.submitter;button.disabled=true;$('loginStatus').textContent='Entrando…';try{await api('/api/admin/login',{method:'POST',body:JSON.stringify({password:$('password').value})});await load()}catch(error){$('loginStatus').textContent=error.message}finally{button.disabled=false}};\n$('filterDate').onchange=load;$('clearFilter').onclick=()=>{$('filterDate').value='';load()};$('refresh').onclick=load;\n$('logout').onclick=async()=>{try{await api('/api/admin/logout',{method:'POST',body:'{}'});showLogin('Você saiu da agenda.')}catch(e){$('adminStatus').textContent=e.message}};\n$('changePassword').onclick=()=>{$('passwordForm').reset();$('passwordStatus').textContent='';$('passwordDialog').showModal()};$('closePassword').onclick=()=>$('passwordDialog').close();\n$('passwordForm').onsubmit=async e=>{e.preventDefault();const button=e.submitter;button.disabled=true;try{await api('/api/admin/password',{method:'POST',body:JSON.stringify({currentPassword:$('currentPassword').value,password:$('newPassword').value})});$('passwordForm').reset();$('passwordDialog').close();showLogin('Senha alterada. Entre com sua nova senha.')}catch(error){$('passwordStatus').textContent=error.message}finally{button.disabled=false}};load();\n","type":"text/javascript; charset=utf-8"}};
const SERVICES={progressiva:{name:'Progressiva',duration:120},selagem:{name:'Selagem',duration:120}};
const encoder=new TextEncoder();
const hex=bytes=>Array.from(new Uint8Array(bytes),x=>x.toString(16).padStart(2,'0')).join('');
const unhex=s=>Uint8Array.from(s.match(/../g)||[],x=>parseInt(x,16));
const random=()=>hex(crypto.getRandomValues(new Uint8Array(32)));
const digest=async value=>hex(await crypto.subtle.digest('SHA-256',encoder.encode(value)));
export async function passwordHash(password,salt=hex(crypto.getRandomValues(new Uint8Array(16)))){const key=await crypto.subtle.importKey('raw',encoder.encode(password),'PBKDF2',false,['deriveBits']);return salt+':'+hex(await crypto.subtle.deriveBits({name:'PBKDF2',hash:'SHA-256',salt:unhex(salt),iterations:100000},key,256));}
function equal(a,b){if(typeof a!=='string'||typeof b!=='string'||a.length!==b.length)return false;let diff=0;for(let i=0;i<a.length;i++)diff|=a.charCodeAt(i)^b.charCodeAt(i);return diff===0;}
function json(body,status=200,headers={}){return new Response(JSON.stringify(body),{status,headers:{'Content-Type':'application/json; charset=utf-8','Cache-Control':'no-store','X-Content-Type-Options':'nosniff',...headers}})}
function fail(message,status=400){return json({error:message},status)}
export function salonNow(){const parts=new Intl.DateTimeFormat('en-CA',{timeZone:'America/Sao_Paulo',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).formatToParts(new Date());const p=Object.fromEntries(parts.map(x=>[x.type,x.value]));return {date:`${p.year}-${p.month}-${p.day}`,minutes:Number(p.hour)*60+Number(p.minute)}}
export function validSlot(date,time,duration,now=salonNow()){if(!/^\d{4}-\d{2}-\d{2}$/.test(date)||!/^\d{2}:00$/.test(time))return false;const d=new Date(date+'T12:00:00Z');if(Number.isNaN(d.getTime())||d.toISOString().slice(0,10)!==date||date<now.date||d.getUTCDay()===0)return false;const horizon=new Date(now.date+'T12:00:00Z');horizon.setUTCFullYear(horizon.getUTCFullYear()+1);if(d>horizon)return false;const start=Number(time.slice(0,2))*60;return start>=540&&start+duration<=1080&&(date!==now.date||start>now.minutes)}
async function body(request){if(Number(request.headers.get('content-length')||0)>4096)throw new Error('body');const text=await request.text();if(text.length>4096)throw new Error('body');return JSON.parse(text)}
async function rate(db,key,limit,seconds){const now=Date.now(),bucket=Math.floor(now/(seconds*1000)),row=await db.prepare('INSERT INTO rate_limits (key,count,expires_at) VALUES (?,1,?) ON CONFLICT(key) DO UPDATE SET count=count+1 RETURNING count').bind(key+':'+bucket,now+seconds*1000).first();return row.count<=limit}
async function auth(request,db){const cookie=request.headers.get('cookie')||'',match=cookie.match(/(?:^|;\s*)__Host-jaiane_admin=([a-f0-9]{64})(?:;|$)/);if(!match)return null;const tokenHash=await digest(match[1]);return await db.prepare('SELECT token_hash FROM admin_sessions WHERE token_hash=? AND expires_at>?').bind(tokenHash,Date.now()).first()}
const cookie=(token,age=28800)=>`__Host-jaiane_admin=${token}; Path=/; HttpOnly; Secure; SameSite=Strict; Max-Age=${age}`;
async function api(request,env,url,ctx){const db=env.DB;if(!db)return fail('Agenda temporariamente indisponível.',503);const path=url.pathname,method=request.method;if(method!=='GET'&&request.headers.get('origin')!==url.origin)return fail('Origem não permitida.',403);
if(path==='/api/availability'&&method==='GET'){const month=url.searchParams.get('month')||'';if(!/^\d{4}-(0[1-9]|1[0-2])$/.test(month))return fail('Mês inválido.');const rows=await db.prepare('SELECT date,time,duration FROM bookings WHERE date LIKE ? ORDER BY date,time').bind(month+'-%').all();return json({bookings:rows.results})}
if(path==='/api/bookings'&&method==='POST'){const ip=await digest(request.headers.get('cf-connecting-ip')||'unknown');if(!await rate(db,'book:'+ip,12,3600))return fail('Muitas reservas. Tente novamente mais tarde.',429);const b=await body(request),s=SERVICES[b.service];if(!['curto','medio','longo','extralongo'].includes(b.hairLength)||!s||typeof b.name!=='string'||b.name.trim().length<2||b.name.length>100||typeof b.phone!=='string'||!/^\d{10,11}$/.test(b.phone.replace(/\D/g,''))||!validSlot(String(b.date),String(b.time),s.duration))return fail('Confira nome, telefone, serviço, data e horário.');const id=crypto.randomUUID(),hour=Number(b.time.slice(0,2)),stmts=[db.prepare('INSERT INTO bookings (id,service,date,time,duration,name,phone,hair_length,created_at) VALUES (?,?,?,?,?,?,?,?,?)').bind(id,s.name,b.date,b.time,s.duration,b.name.trim(),b.phone.replace(/\D/g,''),b.hairLength,Date.now())];for(let i=0;i<s.duration/60;i++)stmts.push(db.prepare('INSERT INTO occupied_slots (date,hour,booking_id) VALUES (?,?,?)').bind(b.date,hour+i,id));try{await db.batch(stmts)}catch(error){if(/UNIQUE|constraint/i.test(String(error)))return fail('Este horário acabou de ser reservado. Escolha outro.',409);throw error}return json({id,message:'Agendamento confirmado!',service:s.name,date:b.date,time:b.time},201)}
if(path==='/api/admin/login'&&method==='POST'){const ip=await digest(request.headers.get('cf-connecting-ip')||'unknown');if(!await rate(db,'login:'+ip,5,900))return fail('Muitas tentativas. Tente novamente em 15 minutos.',429);const b=await body(request);if(typeof b.password!=='string'||b.password.length>128)return fail('Senha inválida.',401);if(!env.ADMIN_BOOTSTRAP_HASH)return fail('Acesso administrativo ainda não configurado.',503);await db.prepare('INSERT OR IGNORE INTO admin_credentials (id,password_hash) VALUES (1,?)').bind(env.ADMIN_BOOTSTRAP_HASH).run();const row=await db.prepare('SELECT password_hash FROM admin_credentials WHERE id=1').first();if(!equal(await passwordHash(b.password,row.password_hash.split(':')[0]),row.password_hash))return fail('Senha inválida.',401);const token=random();await db.prepare('INSERT INTO admin_sessions (token_hash,expires_at) VALUES (?,?)').bind(await digest(token),Date.now()+28800000).run();ctx.waitUntil(db.batch([db.prepare('DELETE FROM admin_sessions WHERE expires_at<?').bind(Date.now()),db.prepare('DELETE FROM rate_limits WHERE expires_at<?').bind(Date.now())]));return json({ok:true},200,{'Set-Cookie':cookie(token)})}
if(path.startsWith('/api/admin/')){const session=await auth(request,db);if(!session)return fail('Entre com a senha para acessar a agenda.',401);
if(path==='/api/admin/bookings'&&method==='GET'){const date=url.searchParams.get('date');if(date&&!/^\d{4}-\d{2}-\d{2}$/.test(date))return fail('Data inválida.');const result=await (date?db.prepare('SELECT * FROM bookings WHERE date=? ORDER BY date,time').bind(date):db.prepare('SELECT * FROM bookings ORDER BY date DESC,time')).all();return json({bookings:result.results})}
if(path==='/api/admin/logout'&&method==='POST'){await db.prepare('DELETE FROM admin_sessions WHERE token_hash=?').bind(session.token_hash).run();return json({ok:true},200,{'Set-Cookie':cookie('',0)})}
if(path==='/api/admin/password'&&method==='POST'){const b=await body(request);if(typeof b.password!=='string'||b.password.length<12||b.password.length>128||typeof b.currentPassword!=='string'||b.currentPassword.length>128)return fail('Use uma nova senha entre 12 e 128 caracteres.');const ip=await digest(request.headers.get('cf-connecting-ip')||'unknown');if(!await rate(db,'change:'+ip,5,900))return fail('Tente novamente em 15 minutos.',429);const row=await db.prepare('SELECT password_hash FROM admin_credentials WHERE id=1').first();if(!equal(await passwordHash(b.currentPassword,row.password_hash.split(':')[0]),row.password_hash))return fail('Senha atual incorreta.',401);await db.batch([db.prepare('UPDATE admin_credentials SET password_hash=? WHERE id=1').bind(await passwordHash(b.password)),db.prepare('DELETE FROM admin_sessions')]);return json({ok:true},200,{'Set-Cookie':cookie('',0)})}
if(path.startsWith('/api/admin/bookings/')&&method==='DELETE'){const id=path.split('/').pop();await db.batch([db.prepare('DELETE FROM occupied_slots WHERE booking_id=?').bind(id),db.prepare('DELETE FROM bookings WHERE id=?').bind(id)]);return json({ok:true})}
}return fail('Não encontrado.',404)}
export default {async fetch(request,env,ctx){const url=new URL(request.url);try{if(url.pathname.startsWith('/api/'))return await api(request,env,url,ctx);if(!['GET','HEAD'].includes(request.method))return fail('Método não permitido.',405);const asset=assets[url.pathname];if(!asset)return new Response('Página não encontrada.',{status:404});return new Response(request.method==='HEAD'?null:asset.body,{headers:{'Content-Type':asset.type,'Cache-Control':'no-store','X-Content-Type-Options':'nosniff','Referrer-Policy':'same-origin','Content-Security-Policy':"default-src 'self'; script-src 'self'; style-src 'self' https://fonts.googleapis.com; font-src https://fonts.gstatic.com; img-src 'self'; connect-src 'self'; base-uri 'self'; form-action 'self'; object-src 'none'"}})}catch(error){console.error('Request failed',error?.message);return fail('Não foi possível concluir. Tente novamente.',500)}}};
